from __future__ import annotations
from typing import Callable, Sequence

def composed_overhead(overheads: Sequence[Callable[[int], int]], cost: int) -> int:
    """Evaluate h_k(...h_2(h_1(cost))...)."""
    if cost < 0:
        raise ValueError("cost must be nonnegative")
    for overhead in overheads:
        cost = overhead(cost)
    return cost

def transport_pointwise_budget(overheads: Sequence[Callable[[int], int]], budget: Sequence[int]) -> list[int]:
    """Transport every sampled budget value through a simulation chain."""
    return [composed_overhead(overheads, value) for value in budget]

from __future__ import annotations
from typing import Sequence

def compare_hierarchy_profiles(a: Sequence[Sequence[bool]], b: Sequence[Sequence[bool]]) -> tuple[bool, list[tuple[int, int]]]:
    """Compare finite class profiles and report every mismatching entry."""
    if len(a) != len(b):
        return False, [(-1, -1)]
    mismatches: list[tuple[int, int]] = []
    for language, (row_a, row_b) in enumerate(zip(a, b)):
        if len(row_a) != len(row_b):
            mismatches.append((language, -1))
            continue
        mismatches.extend((language, level) for level, pair in enumerate(zip(row_a, row_b)) if pair[0] != pair[1])
    return not mismatches, mismatches

from __future__ import annotations
from typing import Sequence

def audit_jump_prefix(current_member: Sequence[bool], successor_absent: Sequence[bool]) -> dict[str, object]:
    """Audit a finite prefix of the two jump-hierarchy axioms."""
    if len(current_member) != len(successor_absent):
        raise ValueError("profiles must have equal lengths")
    failures = [n for n, (member, absent) in enumerate(zip(current_member, successor_absent)) if not (member and absent)]
    return {"valid": not failures, "levels": len(current_member), "failed_levels": failures}

